/**
 * Error boundary-friendly error catcher
 *
 * Wraps functions to catch and handle errors gracefully.
 * Useful for preventing component crashes and logging errors.
 *
 * @module utils/telemetry
 */

import { getMergedRedactKeys, getTelemetryClient } from './config';

/**
 * Error handler callback
 */
export type ErrorHandler = (error: Error, context?: Record<string, unknown>) => void;

/**
 * Options for error catching
 */
export interface CatchErrorsOptions {
  /**
   * Error handler callback
   * Called when wrapped function throws
   */
  readonly onError?: ErrorHandler;

  /**
   * Fallback value to return when error occurs
   * @default undefined
   */
  readonly fallback?: unknown;

  /**
   * Whether to re-throw error after handling
   * @default false (errors are swallowed)
   */
  readonly rethrow?: boolean;

  /**
   * Function name for error context
   * @default fn.name || 'anonymous'
   */
  readonly name?: string;

  /**
   * Additional context to include in error handler
   */
  readonly context?: Record<string, unknown>;

  /**
   * Sensitive keys to redact from context
   *
   * Merged with global defaultRedactKeys unless
   * allowAdditionalRedactKeys is false.
   *
   * @default [] (uses only global defaultRedactKeys)
   */
  readonly redactKeys?: string[];
}

/**
 * Redact sensitive values from context
 *
 * @param context - Context object to redact
 * @param redactKeys - Keys to redact
 * @returns Redacted context
 * @internal
 */
function redactContext(
  context: Record<string, unknown>,
  redactKeys: string[]
): Record<string, unknown> {
  const redacted: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(context)) {
    const lowerKey = key.toLowerCase();
    const shouldRedact = redactKeys.some((redactKey) => lowerKey.includes(redactKey.toLowerCase()));

    // Use Object.assign to avoid Generic Object Injection Sink warning
    Object.assign(redacted, { [key]: shouldRedact ? '[REDACTED]' : value });
  }

  return redacted;
}

/**
 * Wrap a synchronous function with error catching
 *
 * @example
 * ```ts
 * const safeParseJSON = catchErrors(
 *   (json: string) => JSON.parse(json),
 *   {
 *     fallback: null,
 *     onError: (error) => console.error('Parse failed:', error.message)
 *   }
 * );
 *
 * const data = safeParseJSON('invalid json'); // Returns null, doesn't throw
 * ```
 *
 * @example With sensitive data redaction
 * ```ts
 * const processUser = catchErrors(
 *   (user: User) => validateUser(user),
 *   {
 *     name: 'processUser',
 *     context: { userId: user.id, email: user.email },
 *     redactKeys: ['email', 'password'],
 *     onError: (error, context) => {
 *       // context.email is redacted
 *       logger.error('User validation failed', { error, ...context });
 *     }
 *   }
 * );
 * ```
 *
 * @param fn - Function to wrap
 * @param options - Error catching options
 * @returns Wrapped function that catches errors
 */
export function catchErrors<TArgs extends unknown[], TReturn>(
  fn: (...args: TArgs) => TReturn,
  options: CatchErrorsOptions = {}
): (...args: TArgs) => TReturn | undefined {
  const {
    onError,
    fallback,
    rethrow = false,
    name = fn.name || 'anonymous',
    context = {},
    redactKeys = [],
  } = options;

  return function wrappedFunction(...args: TArgs): TReturn | undefined {
    try {
      return fn(...args);
    } catch (error) {
      // Ensure error is Error instance
      const err = error instanceof Error ? error : new Error(String(error));

      // Merge global and per-call redact keys
      const mergedRedactKeys = getMergedRedactKeys(redactKeys);

      // Redact sensitive context
      const safeContext = redactContext({ ...context, function: name }, mergedRedactKeys);

      // Invoke error handler
      if (onError) {
        try {
          onError(err, safeContext);
        } catch {
          // Never throw from error handler
        }
      }

      // Send to global telemetry client if configured
      const client = getTelemetryClient();
      if (client) {
        try {
          client.trackError(err, safeContext);
        } catch {
          // Never throw from telemetry client
        }
      }

      // Re-throw if configured
      if (rethrow) {
        throw err;
      }

      // Return fallback value
      return fallback as TReturn | undefined;
    }
  };
}

/**
 * Wrap an async function with error catching
 *
 * @example
 * ```ts
 * const safeFetch = catchErrorsAsync(
 *   async (url: string) => {
 *     const res = await fetch(url);
 *     return res.json();
 *   },
 *   {
 *     fallback: { error: 'Failed to fetch' },
 *     onError: (error) => console.error('Fetch failed:', error)
 *   }
 * );
 *
 * const data = await safeFetch('/api/data');
 * // Returns fallback if fetch fails
 * ```
 *
 * @example With React error boundary
 * ```ts
 * const fetchUserData = catchErrorsAsync(
 *   loadUserData,
 *   {
 *     name: 'fetchUserData',
 *     onError: (error, context) => {
 *       // Log to external service
 *       errorTracking.captureException(error, context);
 *     },
 *     rethrow: true // Re-throw to trigger error boundary
 *   }
 * );
 * ```
 *
 * @param fn - Async function to wrap
 * @param options - Error catching options
 * @returns Wrapped async function that catches errors
 */
export function catchErrorsAsync<TArgs extends unknown[], TReturn>(
  fn: (...args: TArgs) => Promise<TReturn>,
  options: CatchErrorsOptions = {}
): (...args: TArgs) => Promise<TReturn | undefined> {
  const {
    onError,
    fallback,
    rethrow = false,
    name = fn.name || 'anonymous',
    context = {},
    redactKeys = [],
  } = options;

  return async function wrappedAsyncFunction(...args: TArgs): Promise<TReturn | undefined> {
    try {
      return await fn(...args);
    } catch (error) {
      // Ensure error is Error instance
      const err = error instanceof Error ? error : new Error(String(error));

      // Merge global and per-call redact keys
      const mergedRedactKeys = getMergedRedactKeys(redactKeys);

      // Redact sensitive context
      const safeContext = redactContext({ ...context, function: name }, mergedRedactKeys);

      // Invoke error handler
      if (onError) {
        try {
          onError(err, safeContext);
        } catch {
          // Never throw from error handler
        }
      }

      // Send to global telemetry client if configured
      const client = getTelemetryClient();
      if (client) {
        try {
          client.trackError(err, safeContext);
        } catch {
          // Never throw from telemetry client
        }
      }

      // Re-throw if configured
      if (rethrow) {
        throw err;
      }

      // Return fallback value
      return fallback as TReturn | undefined;
    }
  };
}

/**
 * Global telemetry configuration
 *
 * Provides centralized configuration for telemetry behavior including
 * redaction rules, sampling rates, and integration with external monitoring.
 *
 * @module utils/telemetry
 */

import type { PerformanceMeasurement } from './measurePerformance';

/**
 * Secure-ish random fraction in [0,1) using crypto when available.
 * Falls back to time-based entropy to avoid Math.random for security scanners.
 */
function getSecureRandomFraction(): number {
  const cryptoObj = typeof globalThis.crypto !== 'undefined' ? globalThis.crypto : undefined;
  if (cryptoObj && typeof cryptoObj.getRandomValues === 'function') {
    const buffer = new Uint32Array(1);
    cryptoObj.getRandomValues(buffer);
    const value = buffer[0];
    return (value ?? 0) / 0xffffffff;
  }

  // Deterministic fallback: use time-based entropy
  const timeSlice = Date.now() % 1000;
  return timeSlice / 1000;
}

/**
 * Telemetry client interface for external monitoring integration
 *
 * Implement this interface to integrate with services like:
 * - Datadog
 * - New Relic
 * - Sentry
 * - OpenTelemetry
 * - Custom logging backends
 *
 * @example
 * ```ts
 * const datadogClient: TelemetryClient = {
 *   trackPerformance(measurement) {
 *     DD_RUM.addTiming(measurement.name, measurement.duration);
 *   },
 *   trackError(error, context) {
 *     DD_LOGS.logger.error(error.message, { error, ...context });
 *   }
 * };
 *
 * setTelemetryClient(datadogClient);
 * ```
 */
export interface TelemetryClient {
  /**
   * Track performance measurement
   *
   * @param measurement - Performance measurement data
   */
  trackPerformance(measurement: PerformanceMeasurement & { result?: unknown }): void;

  /**
   * Track error occurrence
   *
   * @param error - Error instance
   * @param context - Additional context data (already redacted)
   */
  trackError(error: Error, context?: Record<string, unknown>): void;
}

/**
 * Global telemetry configuration options
 */
export interface TelemetryGlobalConfig {
  /**
   * Default keys to redact from error context
   *
   * These are merged with per-call redactKeys.
   * Case-insensitive partial matching.
   *
   * @default ['password', 'token', 'secret', 'apiKey', 'accessToken', 'auth']
   */
  defaultRedactKeys: string[];

  /**
   * Whether to allow additional redact keys per call
   *
   * When false, only defaultRedactKeys are used (strict mode).
   *
   * @default true
   */
  allowAdditionalRedactKeys: boolean;

  /**
   * Default sampling rate for performance measurements
   *
   * Value between 0 and 1:
   * - 1.0 = measure every call (100%)
   * - 0.1 = measure 10% of calls
   * - 0 = disable all measurements
   *
   * Can be overridden per measurement.
   *
   * @default 1.0 (measure everything)
   */
  defaultSampleRate: number;
}

/**
 * Default global configuration
 */
const DEFAULT_CONFIG: TelemetryGlobalConfig = {
  defaultRedactKeys: ['password', 'token', 'secret', 'apiKey', 'accessToken', 'auth'],
  allowAdditionalRedactKeys: true,
  defaultSampleRate: 1.0,
};

/**
 * Current global configuration
 */
let globalConfig: TelemetryGlobalConfig = { ...DEFAULT_CONFIG };

/**
 * Current telemetry client (if any)
 */
let telemetryClient: TelemetryClient | null = null;

/**
 * Set global telemetry configuration
 *
 * @example
 * ```ts
 * // Add custom redact keys for healthcare app
 * setTelemetryConfig({
 *   defaultRedactKeys: [
 *     'password', 'token', 'ssn', 'dob', 'medicalRecordNumber'
 *   ]
 * });
 * ```
 *
 * @example
 * ```ts
 * // Enable sampling for high-traffic endpoints
 * setTelemetryConfig({
 *   defaultSampleRate: 0.1 // Only measure 10% of calls
 * });
 * ```
 *
 * @param config - Partial configuration to merge with defaults
 */
export function setTelemetryConfig(config: Partial<TelemetryGlobalConfig>): void {
  globalConfig = { ...globalConfig, ...config };
}

/**
 * Get current global telemetry configuration
 *
 * @returns Current configuration (readonly copy)
 */
export function getTelemetryConfig(): Readonly<TelemetryGlobalConfig> {
  return { ...globalConfig };
}

/**
 * Reset telemetry configuration to defaults
 *
 * Useful for testing or cleanup.
 */
export function resetTelemetryConfig(): void {
  globalConfig = { ...DEFAULT_CONFIG };
}

/**
 * Set global telemetry client for external monitoring
 *
 * @example
 * ```ts
 * // Integrate with Sentry
 * setTelemetryClient({
 *   trackPerformance(measurement) {
 *     Sentry.addBreadcrumb({
 *       category: 'performance',
 *       message: measurement.name,
 *       level: 'info',
 *       data: { duration: measurement.duration }
 *     });
 *   },
 *   trackError(error, context) {
 *     Sentry.captureException(error, {
 *       tags: context,
 *       level: 'error'
 *     });
 *   }
 * });
 * ```
 *
 * @param client - Telemetry client implementation (or null to disable)
 */
export function setTelemetryClient(client: TelemetryClient | null): void {
  telemetryClient = client;
}

/**
 * Get current telemetry client
 *
 * @returns Current client or null if not set
 */
export function getTelemetryClient(): TelemetryClient | null {
  return telemetryClient;
}

/**
 * Get merged redact keys (global + per-call)
 *
 * @param additionalKeys - Per-call redact keys
 * @returns Combined unique redact keys
 * @internal
 */
export function getMergedRedactKeys(additionalKeys: string[] = []): string[] {
  const config = getTelemetryConfig();

  if (!config.allowAdditionalRedactKeys) {
    // Strict mode: only use global keys
    return [...config.defaultRedactKeys];
  }

  // Merge and deduplicate
  const merged = new Set([...config.defaultRedactKeys, ...additionalKeys]);
  return Array.from(merged);
}

/**
 * Check if measurement should be sampled based on sample rate
 *
 * @param sampleRate - Sample rate (0-1), or undefined to use global default
 * @returns True if measurement should proceed
 * @internal
 */
export function shouldSample(sampleRate?: number): boolean {
  const rate = sampleRate ?? getTelemetryConfig().defaultSampleRate;

  // Clamp to valid range
  const clampedRate = Math.max(0, Math.min(1, rate));

  // Always sample if rate is 1
  if (clampedRate >= 1) {
    return true;
  }

  // Never sample if rate is 0
  if (clampedRate <= 0) {
    return false;
  }

  // Probabilistic sampling
  return getSecureRandomFraction() < clampedRate;
}

/**
 * Telemetry utilities
 *
 * Performance measurement, timing, and error tracking utilities.
 * All utilities are SSR-safe and provide zero-overhead when telemetry is disabled.
 *
 * @module utils/telemetry
 */

export { catchErrors, catchErrorsAsync } from './catchErrors';
export type { CatchErrorsOptions, ErrorHandler } from './catchErrors';

export {
  getTelemetryClient,
  getTelemetryConfig,
  resetTelemetryConfig,
  setTelemetryClient,
  setTelemetryConfig,
} from './config';
export type { TelemetryClient, TelemetryGlobalConfig } from './config';

export { endTiming } from './endTiming';

export { measurePerformance, measurePerformanceAsync } from './measurePerformance';
export type { MeasurePerformanceOptions, PerformanceMeasurement } from './measurePerformance';

export { startTiming } from './startTiming';
export type { TimingSession } from './startTiming';

export {
  isTelemetryContext,
  normalizeTelemetryContext,
  type FlexibleContext,
  type TelemetryContext,
} from './types';

export { wrapWithTelemetry, wrapWithTelemetryAsync } from './wrapWithTelemetry';
export type { TelemetryHooks, WrapTelemetryOptions } from './wrapWithTelemetry';

/**
 * Measure function execution time.
 *
 * Uses the Performance API when available and falls back to Date.now() in SSR.
 * Provides accurate millisecond-precision timing for performance monitoring.
 */

/**
 * Performance measurement result.
 */
export interface PerformanceMeasurement {
  /**
   * Duration in milliseconds.
   */
  readonly duration: number;
  /**
   * Operation name.
   */
  readonly name: string;
  /**
   * Start timestamp (from performance.now() or Date.now()).
   */
  readonly startTime: number;
  /**
   * End timestamp (from performance.now() or Date.now()).
   */
  readonly endTime: number;
  /**
   * Optional trace identifier for correlating measurements.
   */
  readonly traceId?: string;
  /**
   * Optional span identifier for nested measurements.
   */
  readonly spanId?: string;
  /**
   * Optional string tags for indexing/aggregation.
   */
  readonly tags?: Record<string, string>;
}

/**
 * Options for measuring performance.
 */
export interface MeasurePerformanceOptions {
  /**
   * Logical name of the operation being measured.
   */
  readonly name?: string;
  /**
   * Callback invoked with the final measurement.
   * Must never throw – we harden against that in the implementation.
   */
  readonly onMeasure?: (measurement: PerformanceMeasurement & { result: unknown }) => void;
  /**
   * Whether to use Performance marks/measures when available.
   * Defaults to true.
   */
  readonly useMarks?: boolean;
  /**
   * Optional sampling rate (0–1). If provided, overrides the global default.
   */
  readonly sampleRate?: number;
  /**
   * Optional trace identifier. If omitted, a new one is generated.
   */
  readonly traceId?: string;
  /**
   * Optional span identifier. If omitted, a new one is generated.
   */
  readonly spanId?: string;
  /**
   * Optional tags to attach to the measurement.
   */
  readonly tags?: Record<string, string>;
}

/**
 * Narrow view of the Performance API that we care about.
 */
type PerformanceLike = Pick<
  Performance,
  'now' | 'mark' | 'measure' | 'clearMarks' | 'clearMeasures'
>;

/**
 * Get Performance API instance from global scope if available.
 *
 * We avoid isBrowser() here on purpose so tests can reliably mock it
 * via (globalThis as any).performance or window.performance.
 */
function getPerformance(): PerformanceLike | undefined {
  const globalPerf = (globalThis as { performance?: PerformanceLike }).performance;

  // In jsdom, window.performance may be separate; prefer global, then window.
  const windowPerf =
    typeof window !== 'undefined'
      ? (window as { performance?: PerformanceLike }).performance
      : undefined;

  const perf = globalPerf ?? windowPerf;
  return perf ?? undefined;
}

/**
 * Get current timestamp with best available precision
 *
 * @returns Milliseconds since epoch (or Performance API origin)
 * @internal
 */
function now(): number {
  const perf = getPerformance();
  if (perf && typeof perf.now === 'function') {
    try {
      return perf.now();
    } catch {
      // Ignore Performance API failures and fall back
    }
  }

  return Date.now();
}

/**
 * Measure a synchronous function.
 */
export function measurePerformance<T>(
  fn: () => T,
  options: MeasurePerformanceOptions = {}
): PerformanceMeasurement & { result: T } {
  const { name = 'anonymous', onMeasure, useMarks = true } = options;

  const perf = getPerformance();
  const hasPerformance = !!perf;
  const canUseMarks =
    hasPerformance &&
    useMarks &&
    typeof perf?.mark === 'function' &&
    typeof perf?.measure === 'function';

  const markStart = `${name}-start`;
  const markEnd = `${name}-end`;

  // Create performance mark if available
  if (canUseMarks && perf) {
    try {
      perf.mark(markStart);
    } catch {
      // Ignore mark errors (quota exceeded, etc.)
    }
  }

  const startTime = now();
  const result = fn();
  const endTime = now();
  const duration = endTime - startTime;

  // Create performance measure if available
  if (canUseMarks && perf) {
    try {
      perf.mark(markEnd);
      perf.measure(name, markStart, markEnd);

      // Clean up marks to avoid memory leaks
      if (typeof perf.clearMarks === 'function') {
        perf.clearMarks(markStart);
        perf.clearMarks(markEnd);
      }
      if (typeof perf.clearMeasures === 'function') {
        perf.clearMeasures(name);
      }
    } catch {
      // Ignore measure errors
    }
  }

  const measurement: PerformanceMeasurement & { result: T } = {
    duration,
    result,
    name,
    startTime,
    endTime,
  };

  if (onMeasure) {
    try {
      onMeasure(measurement);
    } catch {
      // Never throw from callbacks
    }
  }

  return measurement;
}

/**
 * Measure an asynchronous function (Promise-returning).
 */
export async function measurePerformanceAsync<T>(
  fn: () => Promise<T>,
  options: MeasurePerformanceOptions = {}
): Promise<PerformanceMeasurement & { result: T }> {
  const { name = 'anonymous', onMeasure, useMarks = true } = options;

  const perf = getPerformance();
  const hasPerformance = !!perf;
  const canUseMarks =
    hasPerformance &&
    useMarks &&
    typeof perf?.mark === 'function' &&
    typeof perf?.measure === 'function';

  const markStart = `${name}-start`;
  const markEnd = `${name}-end`;

  if (canUseMarks && perf) {
    try {
      perf.mark(markStart);
    } catch {
      // Ignore
    }
  }

  const startTime = now();
  const result = await fn();
  const endTime = now();
  const duration = endTime - startTime;

  if (canUseMarks && perf) {
    try {
      perf.mark(markEnd);
      perf.measure(name, markStart, markEnd);
      if (typeof perf.clearMarks === 'function') {
        perf.clearMarks(markStart);
        perf.clearMarks(markEnd);
      }
      if (typeof perf.clearMeasures === 'function') {
        perf.clearMeasures(name);
      }
    } catch {
      // Ignore
    }
  }

  const measurement: PerformanceMeasurement & { result: T } = {
    duration,
    result,
    name,
    startTime,
    endTime,
  };

  if (onMeasure) {
    try {
      onMeasure(measurement);
    } catch {
      // Never throw from callbacks
    }
  }

  return measurement;
}

/**
 * Start a performance timing session
 *
 * Returns an object that can be used to end the timing and get duration.
 * Useful for measuring operations that span multiple function calls.
 *
 * @module utils/telemetry
 */

import { isBrowser } from '../browser/isBrowser';

/**
 * Active timing session
 */
export interface TimingSession {
  /**
   * Session name/label
   */
  readonly name: string;

  /**
   * Start timestamp (milliseconds)
   */
  readonly startTime: number;

  /**
   * End the timing session and get duration
   *
   * @returns Duration in milliseconds
   */
  end(): number;

  /**
   * Get elapsed time without ending the session
   *
   * @returns Elapsed time in milliseconds
   */
  elapsed(): number;
}

/**
 * Get current timestamp with best available precision
 *
 * @returns Milliseconds
 * @internal
 */
function now(): number {
  if (isBrowser() && typeof performance !== 'undefined' && performance.now) {
    return performance.now();
  }
  return Date.now();
}

/**
 * Start a performance timing session
 *
 * @example
 * ```ts
 * const timer = startTiming('data-processing');
 *
 * // ... do some work ...
 * console.log(`Elapsed: ${timer.elapsed()}ms`);
 *
 * // ... do more work ...
 * const duration = timer.end();
 * console.log(`Total: ${duration}ms`);
 * ```
 *
 * @example With Performance API marks
 * ```ts
 * const timer = startTiming('render');
 * renderComponent();
 * const duration = timer.end();
 * // Automatically creates performance marks/measures
 * ```
 *
 * @param name - Session name/label
 * @returns Timing session object
 */
export function startTiming(name: string): TimingSession {
  const startTime = now();
  let ended = false;
  let cachedDuration: number | null = null;

  const hasPerformance = isBrowser() && typeof performance !== 'undefined';
  const canUseMarks =
    hasPerformance &&
    typeof performance.mark === 'function' &&
    typeof performance.measure === 'function';

  // Create start mark
  if (canUseMarks) {
    try {
      performance.mark(`${name}-start`);
    } catch {
      // Ignore mark errors
    }
  }

  return {
    name,
    startTime,

    elapsed(): number {
      return now() - startTime;
    },

    end(): number {
      if (ended && cachedDuration !== null) {
        // Already ended, return cached duration (idempotent)
        return cachedDuration;
      }

      ended = true;
      const endTime = now();
      const duration = endTime - startTime;
      cachedDuration = duration;

      // Create end mark and measure
      if (canUseMarks) {
        try {
          performance.mark(`${name}-end`);
          performance.measure(name, `${name}-start`, `${name}-end`);

          // Clean up marks to avoid memory leaks
          performance.clearMarks(`${name}-start`);
          performance.clearMarks(`${name}-end`);
          performance.clearMeasures(name);
        } catch {
          // Ignore measure errors
        }
      }

      return duration;
    },
  };
}

/**
 * Telemetry type definitions
 *
 * Structured types for better type safety and PII protection.
 *
 * @module utils/telemetry/types
 */

/**
 * Structured telemetry context
 *
 * Separates string tags (safe for indexing) from arbitrary data (may contain PII).
 * This helps prevent accidental PII leaks in telemetry systems.
 *
 * @example
 * ```ts
 * const context: TelemetryContext = {
 *   tags: {
 *     environment: 'production',
 *     version: '1.2.3',
 *     userId: 'user-123'
 *   },
 *   data: {
 *     requestBody: { ... }, // Complex data
 *     responseTime: 123
 *   }
 * };
 * ```
 */
export interface TelemetryContext {
  /**
   * String key-value pairs for filtering/grouping
   *
   * Tags are typically indexed in telemetry systems.
   * Should only contain non-PII strings.
   *
   * Examples: environment, version, feature flags, user segments
   */
  readonly tags?: Record<string, string>;

  /**
   * Arbitrary data for context
   *
   * Can contain complex objects, numbers, booleans.
   * Should be redacted for sensitive information.
   *
   * Examples: request/response bodies, computed metrics, debug info
   */
  readonly data?: Record<string, unknown>;
}

/**
 * Flexible context type (backward compatible)
 *
 * Accepts either structured TelemetryContext or loose Record.
 * Use TelemetryContext for better type safety and PII protection.
 */
export type FlexibleContext = TelemetryContext | Record<string, unknown>;

/**
 * Type guard for structured TelemetryContext
 *
 * @param context - Context to check
 * @returns True if context has tags/data structure
 *
 * @example
 * ```ts
 * if (isTelemetryContext(context)) {
 *   console.log('Structured context with tags:', context.tags);
 * } else {
 *   console.log('Loose context:', context);
 * }
 * ```
 */
export function isTelemetryContext(context: FlexibleContext): context is TelemetryContext {
  return (
    typeof context === 'object' &&
    context !== null &&
    ('tags' in context || 'data' in context) &&
    !('length' in context) && // Not an array
    Object.keys(context).every((key) => key === 'tags' || key === 'data')
  );
}

/**
 * Normalize flexible context to structured format
 *
 * @param context - Flexible context (structured or loose)
 * @returns Normalized TelemetryContext
 *
 * @example
 * ```ts
 * // Loose context becomes data
 * const normalized = normalizeTelemetryContext({ foo: 'bar', count: 123 });
 * // { tags: {}, data: { foo: 'bar', count: 123 } }
 *
 * // Structured context passes through
 * const normalized = normalizeTelemetryContext({
 *   tags: { env: 'prod' },
 *   data: { count: 123 }
 * });
 * // { tags: { env: 'prod' }, data: { count: 123 } }
 * ```
 */
export function normalizeTelemetryContext(context?: FlexibleContext): TelemetryContext {
  if (!context) {
    return { tags: {}, data: {} };
  }

  if (isTelemetryContext(context)) {
    return {
      tags: context.tags ?? {},
      data: context.data ?? {},
    };
  }

  // Loose context becomes data
  return {
    tags: {},
    data: context,
  };
}

/**
 * Wrap a function with telemetry hooks
 *
 * Automatically measures execution time and captures errors.
 * Preserves function signature and return type.
 *
 * @module utils/telemetry
 */

import type { PerformanceMeasurement } from './measurePerformance';

type TelemetryMeasurement = PerformanceMeasurement & { result?: unknown };

/**
 * Telemetry hooks for wrapped functions
 */
export interface TelemetryHooks {
  /**
   * Called before function execution
   * @param name - Function name
   * @param args - Function arguments
   */
  readonly onStart?: (name: string, args: unknown[]) => void;

  /**
   * Called after successful execution
   * @param measurement - Performance measurement
   */
  readonly onSuccess?: (measurement: TelemetryMeasurement) => void;

  /**
   * Called when function throws error
   * @param error - Error thrown
   * @param duration - Time before error (milliseconds)
   */
  readonly onError?: (error: Error, duration: number) => void;

  /**
   * Called after execution (success or error)
   * @param duration - Total execution time
   */
  readonly onComplete?: (duration: number) => void;
}

/**
 * Options for wrapping function with telemetry
 */
export interface WrapTelemetryOptions extends TelemetryHooks {
  /**
   * Function name for identification
   * @default fn.name || 'anonymous'
   */
  readonly name?: string;

  /**
   * Whether to re-throw errors after capturing
   * @default true
   */
  readonly rethrow?: boolean;
}

/**
 * Get current timestamp (milliseconds)
 * @internal
 */
function now(): number {
  return typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();
}

/**
 * Wrap a synchronous function with telemetry
 *
 * @example
 * ```ts
 * const processData = wrapWithTelemetry(
 *   (data: string[]) => data.map(x => x.toUpperCase()),
 *   {
 *     name: 'processData',
 *     onSuccess: ({ duration }) => console.log(`Took ${duration}ms`),
 *     onError: (error) => console.error('Failed:', error.message)
 *   }
 * );
 *
 * const result = processData(['hello', 'world']);
 * ```
 *
 * @example With analytics integration
 * ```ts
 * const fetchUser = wrapWithTelemetry(
 *   getUserById,
 *   {
 *     name: 'fetchUser',
 *     onSuccess: ({ duration, result }) => {
 *       analytics.track('function_success', {
 *         function: 'fetchUser',
 *         duration,
 *         userId: result.id
 *       });
 *     }
 *   }
 * );
 * ```
 *
 * @param fn - Function to wrap
 * @param options - Telemetry options
 * @returns Wrapped function with same signature
 */
export function wrapWithTelemetry<TArgs extends unknown[], TReturn>(
  fn: (...args: TArgs) => TReturn,
  options: WrapTelemetryOptions = {}
): (...args: TArgs) => TReturn {
  const {
    name = fn.name || 'anonymous',
    onStart,
    onSuccess,
    onError,
    onComplete,
    rethrow = true,
  } = options;

  return function wrappedFunction(...args: TArgs): TReturn {
    const startTime = now();

    // Invoke onStart hook
    if (onStart) {
      try {
        onStart(name, args);
      } catch {
        // Never throw from telemetry hooks
      }
    }

    try {
      const result = fn(...args);
      const endTime = now();
      const duration = endTime - startTime;

      // Invoke onSuccess hook
      if (onSuccess) {
        try {
          onSuccess({
            duration,
            result,
            name,
            startTime,
            endTime,
          });
        } catch {
          // Never throw from hooks
        }
      }

      // Invoke onComplete hook
      if (onComplete) {
        try {
          onComplete(duration);
        } catch {
          // Never throw
        }
      }

      return result;
    } catch (error) {
      const endTime = now();
      const duration = endTime - startTime;

      // Invoke onError hook
      if (onError && error instanceof Error) {
        try {
          onError(error, duration);
        } catch {
          // Never throw from hooks
        }
      }

      // Invoke onComplete hook
      if (onComplete) {
        try {
          onComplete(duration);
        } catch {
          // Never throw
        }
      }

      // Re-throw error if configured
      if (rethrow) {
        throw error;
      }

      // Return undefined if not rethrowing (type system can't express this)
      return undefined as TReturn;
    }
  };
}

/**
 * Wrap an async function with telemetry
 *
 * @example
 * ```ts
 * const fetchData = wrapWithTelemetryAsync(
 *   async (url: string) => {
 *     const res = await fetch(url);
 *     return res.json();
 *   },
 *   {
 *     name: 'api-call',
 *     onSuccess: ({ duration }) => console.log(`API took ${duration}ms`),
 *     onError: (error) => logger.error('API failed', error)
 *   }
 * );
 *
 * const data = await fetchData('/api/users');
 * ```
 *
 * @param fn - Async function to wrap
 * @param options - Telemetry options
 * @returns Wrapped async function with same signature
 */
export function wrapWithTelemetryAsync<TArgs extends unknown[], TReturn>(
  fn: (...args: TArgs) => Promise<TReturn>,
  options: WrapTelemetryOptions = {}
): (...args: TArgs) => Promise<TReturn> {
  const {
    name = fn.name || 'anonymous',
    onStart,
    onSuccess,
    onError,
    onComplete,
