  } = options;

  return async function wrappedAsyncFunction(...args: TArgs): Promise<TReturn> {
    const startTime = now();

    if (onStart) {
      try {
        onStart(name, args);
      } catch {
        // Never throw
      }
    }

    try {
      const result = await fn(...args);
      const endTime = now();
      const duration = endTime - startTime;

      if (onSuccess) {
        try {
          onSuccess({
            duration,
            result,
            name,
            startTime,
            endTime,
          });
        } catch {
          // Never throw
        }
      }

      if (onComplete) {
        try {
          onComplete(duration);
        } catch {
          // Never throw
        }
      }

      return result;
    } catch (error) {
      const endTime = now();
      const duration = endTime - startTime;

      if (onError && error instanceof Error) {
        try {
          onError(error, duration);
        } catch {
          // Never throw
        }
      }

      if (onComplete) {
        try {
          onComplete(duration);
        } catch {
          // Never throw
        }
      }

      if (rethrow) {
        throw error;
      }

      return undefined as TReturn;
    }
  };
}
